 function clearCheckpoint(){try{localStorage.removeItem(ATTEMPT);}catch{}}
 function errorMessage(code){return {blocked:'A wall, locked door or fixed device blocks that step. Use a ladder to change floors.',crate:'No room to push the crate. Crates cannot be pulled.',vent:'Stand on a vent before pressing E',heavy:'The trophy is too heavy for this vent. Use the stairs.',light:'Move next to the wall switch marked L',empty:'No EMP remaining',finished:'This attempt has ended'}[code]||'That action is not available';}
 // CLICK-TO-TRAVEL: walk to a clicked cell one real turn at a time. Before every step the
 // move is simulated with the unchanged engine; the walk stops before any step that would
 // raise an alarm or end the run, and on arrival, a pickup or any key press.
 let travel=null,travelPreview=null,previewAt=0,resultTimer=0; // resultTimer: the result sheet waits ~1100 ms so the board's escape/caught staging can play (none with MOTION OFF).
 // Shortest path that stays out of every cell security covers right now (a fixed camera's field, a live laser); if
 // there is none, the plain shortest path, and the walk still stops before a step that would be seen.
 function routeTo(t){if(!game||!t||t.x==null||t.y<0)return null;const l=game.level,s0=game.state;if(E.tile(l,t.x,t.y)==='#')return null;const key=p=>p.x+','+p.y,danger=new Set();try{const h=E.threats(l,s0);for(const p of [...h.lasers,...h.vision])danger.add(key(p));}catch{}
  const search=avoid=>{const prev=new Map([[key(s0),null]]),q=[{x:s0.x,y:s0.y}];while(q.length){const c=q.shift();if(c.x===t.x&&c.y===t.y){const acts=[];let k=key(c);while(prev.get(k)){const [pk,a]=prev.get(k);acts.unshift(a);k=pk;}return acts;}
   for(const [a,[dx,dy]] of Object.entries(E.DIRS)){const n={x:c.x+dx,y:c.y+dy};if(prev.has(key(n))||E.solid(l,s0,n.x,n.y)||avoid&&danger.has(key(n)))continue;prev.set(key(n),[key(c),a]);q.push(n);}}return null;};
  return (danger.size&&search(true))||search(false);}
 function positions(acts){const out=[{x:game.state.x,y:game.state.y}];let x=game.state.x,y=game.state.y;for(const a of acts){x+=E.DIRS[a][0];y+=E.DIRS[a][1];out.push({x,y});}return out;}
 function stopTravel(msg){if(!travel)return;clearTimeout(travel.timer);travel=null;if(msg)toast(msg);}
 function startTravel(t){const acts=routeTo(t);if(!acts){toast('No open path to that cell right now');return;}if(!acts.length)return;travel={target:{x:t.x,y:t.y},timer:0};travelPreview=null;travelStep();}
 function travelStep(){if(!travel)return;if(!game||game.state.status!=='playing'||paused||SDK?.paused()||$('modal').open||inspectMode||replay||editor?.active){stopTravel();return;}
  const s=game.state;if(s.x===travel.target.x&&s.y===travel.target.y){stopTravel();return;}
  const acts=routeTo(travel.target);if(!acts||!acts.length){stopTravel('The way ahead just closed. Plan your next move.');return;}
  const r=E.step(game.level,s,acts[0]);if(!r.changed){stopTravel();return;}
  if(r.state.status==='lost'||r.state.alarms>s.alarms){stopTravel('Stopped: the next step would be seen. Wait, or pick another route.');renderer.pulse?.(['switch'],performance.now());return;}
  act(acts[0]);const got=game.state.events.some(e=>['key','relic','intel','switch'].includes(e));if(got||game.state.status!=='playing'){stopTravel();return;}
  travel.timer=setTimeout(travelStep,save.reduced?60:125);}
 function act(a){if(inspectMode){scanAction(a);return;}if(!readyGame()||paused||SDK?.paused()||$('modal').open||game.state.status!=='playing')return;if(owned&&Date.now()-owned.checkedAt>300000)recheckOwned();const now=performance.now();if(now-lastInput<95)return;const q=E.step(game.level,game.state,a);if(!q.changed){toast(errorMessage(q.error));return;}lastInput=now;anim={from:{x:game.state.x,y:game.state.y},start:now,end:now+(save.reduced?0:140)};game.trail=[...(game.trail||[]),{x:game.state.x,y:game.state.y}].slice(-10);game.state=q.state;game.actions.push(a);renderer.pulse?.(q.state.events,now);if(q.state.events.includes('intel')&&E.countIntel(q.state)===1)$('liveAnnounce').textContent='Security plans taken. Every patrol route and camera sweep is now drawn on the building.';beep(q.state.events.includes('alarm')?'alarm':q.state.events.includes('key')?'key':'step');hud();checkpoint();if(q.state.status!=='playing'){record();const g=game;clearTimeout(resultTimer);if(save.reduced)result();else resultTimer=setTimeout(()=>{if(game===g&&screen==='play'&&!replay&&!editor?.active)result();},1100);}}
 function record(){if(game.recorded||game.shared||game.type==='test'||game.type==='fortify')return;game.recorded=true;const s=game.state,r={v:1,at:new Date().toISOString(),level:game.level,actions:[...game.actions],mode:s.mode,practice:game.practice,heroId:hero.tokenId,status:s.status};save.records.unshift(r);save.records=save.records.slice(0,30);if(s.status==='won'){const official=byId(game.level.id);if(official&&!game.practice&&F.planKey(official)===F.planKey(game.level))save.mastery[official.id]=F.mergeTarget(save.mastery[official.id],official,s,false);if(!save.done.includes(game.level.id)){save.done.push(game.level.id);game.firstClear=true;}if(!game.practice&&(!official||F.planKey(official)===F.planKey(game.level))){const k=game.level.id+':'+s.mode;save.best[k]=Math.max(save.best[k]||0,E.score(game.level,s));}}persist();}
 // Result sheet: one verdict, one main action, the rest as quiet links. No alarm counter.
 // v2 rules: a won job is never seen, so the medal is 'ghost' (no EMP, within PAR) or 'clean'.
 function medalOf(l,s){if(s.status!=='won')return null;if(game.practice)return 'practice';return s.empUsed===0&&s.turn<=l.par?'ghost':'clean';}
 function result(){const s=game.state,l=game.level,analysis=F.summary(l,game.actions,s.mode),next=game.type==='training'?lessons[lessons.findIndex(x=>x.id===l.id)+1]:game.type==='solo'?nextJob(l):null;record();beep(s.status==='won'?'win':'alarm');
  const won=s.status==='won',medal=medalOf(l,s),locked=s.failure?.kind==='lockdown',intel=E.positions(l,'o').length,lesson=game.type==='training',first=won&&!!game.firstClear&&(lesson||!game.practice);
  game.failAt=game.actions.length;game.failSource=analysis.source;const stampText=won&&lesson?(game.practice?'PRACTICE':'CLEARED'):{practice:'PRACTICE',ghost:'GHOST',clean:'CLEAN'}[medal]||(locked?'LOCKED IN':'SPOTTED');
  const title=won?(lesson?'LESSON CLEARED':game.practice?'PRACTICE RUN DONE':'YOU GOT OUT'):locked?'TIME RAN OUT':'MISSION FAILED';
  const verdict=won&&lesson?(game.practice?'Rewinds are fine in a lesson. Play it again without Z for a clean clear.':next?'Clean clear. Next lesson: '+next.name+'.':'All '+lessons.length+' lessons cleared. Every job on the street is open.'):won?({practice:'Rewinds make this a practice run: no score, no goals, no proof. Retry for a clean run.',ghost:'Unseen, no EMP, within par. The best way out.',clean:'Out unseen. Beat '+l.par+' turns without EMP for GHOST.'}[medal]):failureText(s.failure,analysis.source)+(locked?' Take the trophy only when the way back is ready.':' Dashed boxes show next turn\'s danger; check them before you step.');
  const home=SDK?'ALL JOBS':['solo','training','daily','replay'].includes(game.type)?'ALL JOBS':'STREET';
  let main='',more='';
  if(won&&next&&!game.shared)main+='<button id="resultNext" class="primary">'+(game.type==='training'?'NEXT LESSON':'NEXT JOB')+' &gt;</button>';
  if(game.type==='training'&&won&&!next)main+='<button id="resultCampaign" class="primary">START THE JOBS &gt;</button>';
  if(game.type==='test')main+='<button id="resultEditor" class="primary">BACK TO EDITOR</button>';
  if(game.shared&&game.type==='shared')main+='<button id="submitShared" class="primary">SUBMIT TO SERVER</button>';
  if(game.type==='fortify'&&won&&!game.practice)main+='<button id="submitFortify" class="primary">PUBLISH CHANGE</button>';
  main+='<button id="resultRetry"'+(main?'':' class="primary"')+'>RETRY</button>';
  if(!won)main+='<button id="resultCause">SHOW WHAT SAW ME</button>';
  if(!game.shared&&game.type!=='fortify'&&!won)main+='<button id="resultUndo">REWIND 5 TURNS</button>';
  if(!won)more+='<button id="resultLastFive">REPLAY LAST 5 TURNS</button>';
  if(!won&&['solo','training','daily'].includes(game.type)&&solutionFor(l))more+='<button id="resultSolution">WATCH SOLUTION</button>';
  if(!game.shared&&game.type!=='fortify'&&game.type!=='test')more+='<button id="resultReplay">WATCH WHOLE ROUTE</button>'+(SDK?'':'<button id="resultCard">SAVE PICTURE</button><button id="resultRemix">REMIX IN WORKSHOP</button>');
  more+='<button id="resultHome">'+home+'</button>';
  let body='<div class="verdict"><div class="stamp'+(won?'':' lost')+'">'+stampText+'</div><p>'+escape(verdict)+'</p></div><div class="res-friend '+(won?'out':'caught')+'"><canvas class="res-stage" aria-hidden="true"></canvas><span>'+(first?'<i class="firstclear">'+(lesson?'FIRST LESSON CLEAR':'FIRST CLEAR')+'</i>':'')+'<b>#'+escape(hero.tokenId)+' '+escape(String(hero.familyName||'').toUpperCase())+'</b>'+(won?'got out':locked?'was locked in':'was spotted')+'<br>'+friendRole().toLowerCase().replace(/^./,c=>c.toUpperCase())+'</span></div>'
   +'<div class="resultstats"><div>TURNS<strong>'+s.turn+'</strong><small>PAR '+l.par+'</small></div><div>INTEL<strong>'+E.countIntel(s)+' / '+intel+'</strong><small>'+(intel?'OPTIONAL':'NONE HERE')+'</small></div><div>EMP USED<strong>'+s.empUsed+'</strong><small>'+(s.empUsed?'NOT CLEAN':'NONE')+'</small></div></div>'
   +'<div class="resultmain">'+main+'</div>';
  if(!won&&(analysis.source||locked))body+='<div class="debrief">'+(analysis.source?'<p>'+escape(sourceName(s.failure,analysis.source)+(analysis.source.kind==='drone'?' caught you':' saw you')+' on '+F.floor(l,s.y)+', column '+s.x+', after move '+s.turn+'. '+(analysis.source.crossed?'You and the '+(s.failure?.kind==='walker'?'guard':'drone')+' crossed paths.':analysis.source.kind==='drone'?'You stepped into its cell.':'You stepped into its field.'))+'</p>':'')+(locked?'<p>The escape timer reached zero. Plan keys and the way back before taking the trophy.</p>':'')+'<p>'+analysis.waits+' waits, '+analysis.pushes+' pushes</p></div>';
  if(won&&!game.shared&&!['test','fortify','training'].includes(game.type))body+='<div class="goalbox">'+targetHTML(l,F.targets(l,s,game.practice))+'<p class="note">Goals are saved on this device and can be earned on different runs. Practice earns none.</p></div>';
  body+='<div class="resultmore">'+more+'</div>';
  if(game.shared&&won&&game.type==='shared')body+='<p class="note">The server replays your route before anything changes.</p>';
  modal(title,body);stageOn($('dialogContent').querySelector('.res-stage'),hero,first?'celebrate':won?'escaped':'caught');
  ($('resultNext')||$('resultCampaign')||$('submitShared')||$('submitFortify')||$('resultEditor')||$('resultRetry')).focus({preventScroll:true});$('dialogContent').parentElement.scrollTop=0;
  if($('resultNext'))$('resultNext').onclick=()=>{$('modal').close();start(next,{type:game.type,mode:game.state.mode});};
  if($('resultCause'))$('resultCause').onclick=()=>{$('modal').close();incident=analysis.source;inspectCell=analysis.source?.origin||{x:s.x,y:s.y};setInspect(true);};
  if($('resultSolution'))$('resultSolution').onclick=()=>{$('modal').close();watchSolution(l,'solo');};if($('resultLastFive'))$('resultLastFive').onclick=()=>{const r={level:game.level,actions:game.actions,mode:s.mode,heroId:hero.tokenId};$('modal').close();watch(r,analysis.reviewStart);};
  $('resultRetry').onclick=()=>{$('modal').close();retry();};if($('resultReplay'))$('resultReplay').onclick=()=>{const r={level:game.level,actions:game.actions,mode:s.mode,heroId:hero.tokenId};$('modal').close();watch(r);};$('resultHome').onclick=()=>{$('modal').close();navigate(home==='ALL JOBS'?'solo':'street');};if($('resultUndo'))$('resultUndo').onclick=()=>{$('modal').close();undo(5);};if($('resultCampaign'))$('resultCampaign').onclick=()=>{$('modal').close();navigate('solo');};if($('resultEditor'))$('resultEditor').onclick=()=>{if(s.status==='won'&&!game.practice&&editor&&JSON.stringify(game.level)===JSON.stringify(C.normalize(editor.draft)))editor.proof=[...game.actions];$('modal').close();openEditor();};if($('resultCard'))$('resultCard').onclick=exportCard;if($('resultRemix'))$('resultRemix').onclick=()=>{const source=clone(game.level);source.id='custom-cutaway';source.name=source.nameEn='Remix / '+source.name;editor={kind:'workshop',draft:source,history:[],proof:null,tool:'wall'};$('modal').close();saveDraft();openEditor();};if($('submitShared'))$('submitShared').onclick=submitShared;if($('submitFortify'))$('submitFortify').onclick=publishFortify;
 }
 function exportCard(){if(!game)return;const c=document.createElement('canvas');c.width=960;c.height=720;const g=c.getContext('2d');P.rect(g,0,0,960,720,P.PAPER);P.rect(g,0,0,960,75);P.text(g,'RARE HEIST / CUTAWAY',24,18,3,P.PAPER);P.text(g,game.level.name,24,52,2,P.SIG);const v=document.createElement('canvas');HeistCutawayRenderer.create(v).render(game.level,game.state,{sample:hero,width:960,height:510,reduced:true,time:0});g.drawImage(v,0,76);P.rect(g,0,594,960,126);P.text(g,(game.state.status==='won'?({practice:'PRACTICE',ghost:'GHOST',clean:'CLEAN'}[medalOf(game.level,game.state)]||'CLEAN'):'SPOTTED')+' / '+game.state.turn+' TURNS / '+E.countIntel(game.state)+' INTEL',24,617,3,P.SIG);P.text(g,'ORIGINAL FRIEND #'+hero.tokenId+' / NO REAL FUNDS',24,670,2,P.PAPER);c.toBlob(blob=>{if(!blob)return toast('Export unavailable in this browser');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rare-heist-extraction.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'image/png');}
 function retry(){if(!game)return;if(game.shared){enterRound();return;}const keep={type:game.type,mode:game.state.mode,practice:false,mutation:game.mutation};start(game.level,keep);}
