 // Home hero: the one obvious next step, and the Friend who will play it.
 function nextPlay(){const done=id=>save.done.includes(id);if(!lessons.some(l=>done(l.id)))return {level:lessons[0],opts:{type:'training'},label:'PLAY',note:'Free. No wallet needed. Starts with a one-minute lesson.'};const job=campaign.find(l=>!done(l.id));if(job)return {level:job,opts:{},label:'CONTINUE',note:'Next: job '+(campaign.indexOf(job)+1)+' of '+campaign.length+', '+job.name};return {level:null,label:'ALL JOBS',note:'All '+campaign.length+' street jobs cleared. Try the annex, GHOST runs, or the shared Last Heist.'};}
