 async function recheckOwned(){if(!owned||recheckOwned.busy||!wallet.provider)return;recheckOwned.busy=true;try{const v=await HeistIdentity.read(wallet.provider,hero.tokenId);owned={...owned,...v,sample:hero,checkedAt:Date.now()};}catch(e){owned=null;previewing=true;if(save.friend)save.friend.mode='preview';persist();settings();toast('Ownership could not be confirmed ('+e.message+'). Your Friend stays as PREVIEW.');}finally{recheckOwned.busy=false;}}
