  const AWAITING_WALLET_TEXT='Confirm or reject the previous burn in your wallet first.',OTHER_TAB_WALLET_TEXT='Waiting for your wallet in another tab.',UNKNOWN_OUTCOME_TEXT="We don't know if your wallet sent the burn. Check your wallet's activity before trying again.";
