  +'<dl class="stakehero-facts"><div><dt>Entrants in live pots</dt><dd id="ecEntrants">...</dd></div><div><dt>Burned by stake rounds so far</dt><dd id="ecStakeBurned">...</dd></div><div><dt>Settled stake rounds</dt><dd id="ecSettled">...</dd></div></dl></div>'
