   +'<div class="face-row" role="group" aria-label="Laser and camera facing"><span>FACING</span><button data-face="W">&#9664; LEFT</button><button data-face="E">RIGHT &#9654;</button></div>'
   +'<ol class="checks" aria-label="Checks for your change"><li data-check="place"><i class="ck" aria-hidden="true"></i><span></span></li><li data-check="breaks"><i class="ck" aria-hidden="true"></i><span></span></li><li data-check="beatable"><i class="ck" aria-hidden="true"></i><span></span></li></ol>';
