  const piece=k=>tools.find(t=>t[0]===k)[1];
  if(m)set('place','bad','NOT HERE:',escape(m.text)+(editor.change?' Your '+piece(editor.change.kind).toLowerCase()+' stays at '+F.floor(editor.round.level,editor.change.y)+', column '+editor.change.x+'.':''));else if(editor.change)set('place','ok',escape(tools.find(t=>t[0]===editor.change.kind)[1])+' PLACED',where(editor.change)+'.');else set('place','wait','PLACE ONE PIECE',touchCopy('Drag it onto a floor cell, or click it and then a cell.'));
  if(!editor.change)set('breaks','wait','BREAK THE LAST WINNING ROUTE','It is the dotted line.');else if(c.breaks)set('breaks','ok','BREAKS THE LAST WINNING ROUTE','The cut is marked on the dotted line.');else set('breaks','bad','THE LAST WINNING ROUTE STILL WORKS','Put the piece on the dotted line.');
  const sv=c?.solve;if(!sv)set('beatable','wait','STILL BEATABLE?','The solver checks every route.');else if(sv.state==='running')set('beatable','run','CHECKING EVERY ROUTE…',(sv.nodes||0).toLocaleString('en-US')+' positions so far.');else if(sv.state==='ok')set('beatable','ok','STILL BEATABLE:','the solver found a '+sv.turns+'-turn route. Now clear it yourself.');else if(sv.state==='blocked')set('beatable','bad','THIS BLOCKS EVERY ROUTE:','no way out within '+A.MAX_ACTIONS+' turns. Move it.');else set('beatable','unknown','COULD NOT VERIFY IN TIME','You can still try to clear it yourself.');
  const ready=fortifyReady();$('testRoom').disabled=!ready;$('testRoom').title=ready?'Clear the vault with your change in place. No EMP, no rewinds.':'Available when your change breaks the last route and can still be beaten.';$('publishRoom').disabled=!(editor.proof&&editor.change);
  const status=message||(editor.proof?'Proof ready. PUBLISH CHANGE before the edit window closes.':m?'Not here: '+m.text:!editor.change?'Drag a wall, laser or camera onto the dotted route.':!c.breaks?'Your piece misses the last winning route.':sv?.state==='blocked'?'Nobody could clear that. Move the piece.':sv?.state==='running'?'Checking that the vault can still be beaten...':'Now PROVE YOUR CHANGE: clear the vault yourself.');
