 function testRoom(){if(!editor)return;if(editor.kind==='fortify'&&!fortifyReady()){fortifyRender();toast(editor.change?$('editStatus').textContent:'Place one wall, laser or camera first');return;}try{const l=C.normalize(editor.draft);start(l,{type:editor.kind==='fortify'?'fortify':'test',mode:'ghost',mutation:editor.change});}catch(e){editorFeedback(e.message);}}
 function exportProof(){if(editor?.kind==='fortify'){publishFortify();return;}if(!editor?.proof)return toast('Complete a clean test of this exact revision first');const l=C.normalize(editor.draft),q=E.replay(l,editor.proof,'ghost');if(!q.ok)return toast('Proof expired. Test again.');download('rare-heist-cutaway.json',JSON.stringify({format:'rare-heist-cutaway-1',level:l,proof:editor.proof},null,2),'application/json');toast('Exported a playable room and its proof');}
 function importRoom(){modal('IMPORT A CUTAWAY','<p>Optional workshop exchange. The shared Last Heist does not require imports. Only cutaway rooms are accepted; old isometric layouts remain in the older build.</p><textarea id="roomData" placeholder="Paste a cutaway room JSON"></textarea><input id="roomFile" type="file" accept=".json,application/json"><button id="importConfirm" class="primary">OPEN IN WORKSHOP</button><p id="importError" class="note"></p>');$('roomFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>65536)return $('importError').textContent='Maximum 64 KB';$('roomData').value=await f.text();};$('importConfirm').onclick=()=>{try{const t=$('roomData').value;if(t.length>65536)throw Error('Maximum 64 KB');const r=JSON.parse(t),l=C.normalize(r.level||r);editor={kind:'workshop',draft:l,history:[],proof:null,tool:'wall'};if(r.proof&&E.replay(l,r.proof,'ghost').ok)editor.proof=r.proof;$('modal').close();openEditor();}catch(e){$('importError').textContent=e.message;}};}
 /* Shared service. No local rehearsal is silently presented as online. */
 async function ensureClient(){if(client?.me)return client;client=new LastHeistClient.Network();await client.init();return client;}
 // The published server build (README "PLAY IN YOUR BROWSER"). Static copies link there for shared rounds.
 const LIVE_HOST='rareheist-bc89faa0.sslip.io';
 const lastHead='<div class="pagehead"><div><h1>LAST HEIST</h1><p class="lede">One shared vault on the game server. Stake in, clear it, add one obstacle that stops the last winning route, then hold the lead until the timer ends. In a stake round the winner takes 70% of the pot and 30% is burned, in DEMO RF for now.</p></div></div>';
 const lastSteps='<div class="steps"><div><strong>CLEAR IT</strong>Get the trophy out unseen. No EMP, no rewinds.</div><div><strong>ADD ONE OBSTACLE</strong>A wall, laser or camera that blocks the last route. Then prove your version can still be cleared.</div><div><strong>DEFEND</strong>The last verified thief when the timer ends wins the round\'s DEMO RF (play money).</div></div>';
 async function showShared(){if(onlineBusy)return;onlineBusy=true;$('lastPage').innerHTML=lastHead+'<p class="statusline" role="status">Connecting to the game server...</p>';try{await ensureClient();const rs=await client.list();if(!shared||!rs.some(r=>r.id===shared.id)){const live=rs.filter(r=>r.phase!=='finished'),busy=(a,b)=>b.attemptCount-a.attemptCount;shared=live.filter(r=>r.stake).sort(busy)[0]||live.filter(r=>r.profile==='standard').sort(busy)[0]||live.sort(busy)[0]||rs[0];}if(shared)shared=await client.round(shared.id);renderShared(rs);}catch(e){const here=location.hostname===LIVE_HOST;$('lastPage').innerHTML=lastHead+'<div class="offline"><div><p class="statusline" role="status">'+(here?'The game server did not answer: '+escape(e.message):'This copy has no game server, so shared rounds are off here.')+'</p>'+lastSteps+'<p class="note">'+(here?'Try again in a moment. Solo jobs work without the server.':'This copy (a download or the static mirror) runs every solo job. The shared vault runs on the online version.')+'</p><div class="toolbar">'+(here?'':'<a class="btnlink primary" href="https://'+LIVE_HOST+'/" rel="noopener">OPEN THE ONLINE VERSION</a>')+'<button data-route="solo"'+(here?' class="primary"':'')+'>PLAY SOLO VAULTS</button><button id="retryConnect">TRY AGAIN</button></div></div><div class="vaultdoor" aria-hidden="true"><i></i><i></i><i></i><b></b></div></div>';$('retryConnect').onclick=showShared;}finally{onlineBusy=false;}}
 function bannerText(r){if(r.phase==='finished')return 'THIS ROUND HAS ENDED. A finished round cannot change.';if(fortifyOpen())return 'YOUR EDIT WINDOW: '+timeLeft(r)+' LEFT. Add one obstacle and prove a clean route before it closes.';if(r.phase==='editing')return 'LIVE ROUND, VERSION '+r.revision+': THE LEADER IS EDITING, '+timeLeft(r)+' LEFT';if(r.phase==='waiting')return 'LIVE ROUND, VERSION '+r.revision+': WAITING FOR THE FIRST THIEF';return 'LIVE ROUND, VERSION '+r.revision+', OPEN: '+timeLeft(r)+' LEFT. Pausing does not stop this clock.';}
 // The edit lease is over when the server says so, or when the local copy of the server clock passes it.
 function editWindowClosed(){if(!shared||!fortifyOpen()||onlineBusy)return false;const id=editor?.round?.id;if(id&&id!==shared.id)return false;if(shared.phase!=='editing'||shared.canEdit===false)return true;return !!shared.editUntil&&Date.now()+(shared._offset||0)>=shared.editUntil;}
 function leaveEditor(){const rev=shared?.revision??0;editor=null;clearTimeout(resultTimer);clearCheckpoint();if($('modal').open)$('modal').close();game=null;lastNotice={text:'EDIT WINDOW CLOSED. Your obstacle was not published: version '+rev+' stays and the vault is open for raids again.',until:Date.now()+30000};toast('Edit window closed. Your change was not published.');navigate('last');}
 function setRound(r){shared=r;shared._offset=r.serverNow-Date.now();}
 function timeLeft(r){if(!r||r.phase==='waiting')return 'WAITING';if(r.phase==='finished')return 'FINISHED';const end=r.phase==='editing'?r.editUntil:r.deadline,ms=Math.max(0,end-(Date.now()+(r._offset||0)));return String(Math.floor(Math.ceil(ms/1000)/60)).padStart(2,'0')+':'+String(Math.ceil(ms/1000)%60).padStart(2,'0');}
 // LAST HEIST lobby. Players appear as their Friend: its own frame, #ID and the server name ("Friend #ID" by default).
 const PROFILE_NAME={standard:'STANDARD, 10 MIN',sprint:'SPRINT, 90 S'};
 const playerTag=id=>String(id||'').slice(0,4).toUpperCase();
 function who(r,id){const h=r.heroes?.[id];return (h?chip(h,''):'')+'<span class="pname">'+escape(r.names?.[id]||'Guest')+'</span>';}
 function outcomeText(r,e=r){const lead=e.player||r.leader;return e.outcome==='winner'?(lead?who(r,lead):'The leader')+' held the vault and wins the round.':e.outcome==='uncontested'?(lead?who(r,lead)+' cleared it, but':'Only one session cleared it, so')+' a prize needs two clearing sessions.':'Nobody cleared this vault.';}
 function eventLine(r,e){const w=e.player?who(r,e.player):'A guest',t={started:'Round started. The vault is open.',clear:w+' cleared it'+(e.turns?' in '+escape(e.turns)+' turns':'')+'.',fortified:w+' added a '+escape(String(e.change?.kind||'change'))+'.',skipped:w+' kept the vault as it was.','edit-expired':'The edit window closed with no change.',settled:'Round over. '+outcomeText(r,e),claimed:w+' collected '+escape(e.amount)+' DEMO RF.'}[e.type];return '<li><span class="ev-v">V'+escape(e.revision)+'</span><span>'+(t||escape(String(e.type).toUpperCase()))+'</span></li>';}
 // Stake rounds come first: they are the core loop. One tab per live round. Untouched rounds (waiting, version 0, no attempts) of the same length are the same vault: show one.
 function roundTabs(rs,cur){const idle=v=>v.phase==='waiting'&&!v.attemptCount&&!v.revision,rep=new Map(),order=v=>v.stake?0:v.profile==='standard'?1:2;for(const v of rs){if(v.phase==='finished'&&v.id!==cur.id)continue;const k=idle(v)?'idle:'+v.profile+(v.stake?':stake':''):v.id;if(!rep.has(k)||v.id===cur.id)rep.set(k,v);}return [...rep.values()].sort((a,b)=>order(a)-order(b));}
 const tabState=v=>v.phase==='waiting'?'WAITING':v.phase==='open'?'OPEN':v.phase==='editing'?'EDITING':'ENDED';
