 function houseRun(r){const acts=houseRoute(r.level);if(!acts){toast('The house route does not clear this version.');return;}replayFriends.set(hero.tokenId,hero);watch({level:r.level,actions:acts,mode:'ghost',heroId:hero.tokenId},0,{house:true,fromLast:true});replay.playing=true;$('replayToggle').textContent='PAUSE';$('sharedBanner').hidden=false;$('sharedBanner').textContent='HOUSE RUN: a solver demo of version '+r.revision+', walked by your Friend. Not a player: it never leads, scores or counts as an attempt.';}
 let lastNotice=null; // {text, until}: a lobby notice that survives the 3.5 s refreshes for half a minute
