 function stakeLine(h){return h.outcome==='winner'?chip(h.hero,'')+'<span class="pname">'+escape(h.winnerName||'The winner')+'</span> took '+num(h.paid)+' DEMO RF · '+num(h.burned)+' DEMO RF burned':'Every stake refunded: '+num(h.refunded)+' DEMO RF back to '+h.entrants+' entrant'+(h.entrants===1?'':'s')+'.';}
