  const bar=st?settledCard(r,st):'<div class="potbar" role="img" aria-label="If the round ended with a winner now: '+s.projected.winner+' DEMO RF to the winner, '+s.projected.burned+' DEMO RF burned"><span class="win" style="flex:'+s.winnerPct+'"><b>'+num(s.projected.winner)+'</b>'+pct(s.winnerPct)+' TO THE WINNER</span><span class="ash" style="flex:'+s.burnPct+'"><b id="stakeWouldBurn">'+num(s.projected.burned)+'</b>'+pct(s.burnPct)+' BURNS</span></div>';
  const who=s.entrants.length?'<ul class="entrants" aria-label="Entrants">'+s.entrants.map(e=>'<li'+(e.you?' class="you"':'')+'>'+chip(e.hero,'')+'<span>'+escape(e.name)+(e.you?' (you)':'')+'</span></li>').join('')+'</ul>':'<p class="entrants-none">No stakes yet. The first entrant opens the pot.</p>';
  return '<section class="stakes" id="stakePanel" aria-labelledby="stakeHead"><div class="stakes-head"><strong id="stakeHead">'+s.entrants.length+' × '+s.amount+' DEMO RF STAKE'+(s.entrants.length===1?'':'S')+'</strong>'+demoStamp+'</div>'
