   +(info?'<p class="stakes-counter">With real RF, stake rounds would have burned <b id="stakeBurnedAll">'+num(info.totals.burned)+' RF</b> so far ('+num(info.totals.settledRounds)+' settled round'+(info.totals.settledRounds===1?'':'s')+').</p>':'')
